import React, { useState, useMemo, useEffect } from 'react';

// --- Icon Components ---
const EditIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"></path><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"></path></svg>
);
const InfoIcon = () => (
    <svg xmlns="http://www.w.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"></circle><line x1="12" y1="16" x2="12" y2="12"></line><line x1="12" y1="8" x2="12.01" y2="8"></line></svg>
);
const SaveIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg>
);
const CancelIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
);


export default function WDPerDeliveryAllocationTab({ subject }) {
    // --- STATE MANAGEMENT ---
    const [allocations, setAllocations] = useState([]);
    const { deliveries } = useWorkload();
    const [editingId, setEditingId] = useState(null);
    const [editValue, setEditValue] = useState('');
    const [error, setError] = useState('');

    // Initialize state when the subject prop is available or changes
    useEffect(() => {
        const initialData = subject?.perDeliveryAllocation || [];
        // Add an 'originalValue' to revert to on cancel
        setAllocations(initialData.map(item => ({...item, originalValue: item.allocationToSubjectCoordinationTeam })));
    }, [subject]);

    // --- CALCULATION LOGIC ---
    const calculationInputs = subject?.calculationInputs || {};
    const subjectCoordinatorName = subject?.subjectCoordinator || 'N/A';

    // Memoized calculations prevent re-computing on every render
    const calculatedData = useMemo(() => {
        const lecturerAllocations = allocations.map(row => 
            Math.max(0, row.baseAllocation - row.allocationToSubjectCoordinationTeam)
        );

        const increaseOfBaseAllocation = lecturerAllocations.reduce((sum, current) => sum + current, 0);

        const sumCoordTeamAllocation = allocations.reduce((sum, row) => sum + row.allocationToSubjectCoordinationTeam, 0);

        let subjectCoordinatorAllocation = 0;
        if (calculationInputs.isManagedBySCDMS === 'Yes') {
            if (sumCoordTeamAllocation > 0) {
                 subjectCoordinatorAllocation = 0.01 * (calculationInputs.totalStudentHours || 0) * Math.max(...lecturerAllocations, 0);
            }
        }

        return { increaseOfBaseAllocation, subjectCoordinatorAllocation };
    }, [allocations, calculationInputs]);


    // --- EVENT HANDLERS ---
    const handleEdit = (row) => {
        setEditingId(row.id);
        setEditValue(String(row.allocationToSubjectCoordinationTeam));
        setError('');
    };

    const handleCancel = () => {
        setEditingId(null);
        setError('');
    };

    const handleSave = () => {
        const numericValue = parseFloat(editValue);
        const editingRow = allocations.find(row => row.id === editingId);

        // Validation
        if (isNaN(numericValue) || numericValue < 0 || numericValue > editingRow.baseAllocation) {
            setError(`Value must be between 0 and ${editingRow.baseAllocation}.`);
            return;
        }

        setAllocations(allocations.map(row => 
            row.id === editingId 
            ? { ...row, allocationToSubjectCoordinationTeam: numericValue, originalValue: numericValue } 
            : row
        ));
        setEditingId(null);
        setError('');
    };

    const handleInputChange = (e) => {
        setEditValue(e.target.value);
        if (error) setError('');
    };

    return (
        <div style={styles.tabContentContainer}>
            <h3 style={styles.tabTitle}>
                Per-delivery Allocation
                <span style={styles.infoIconWrapper} title="Edit allocations for the coordination team per delivery location.">
                    <InfoIcon />
                </span>
            </h3>

            <table style={styles.table}>
                <thead>
                    <tr>
                        <th style={{...styles.tableHeaderCell, width: '80px', textAlign: 'center'}}>Actions</th>
                        <th style={styles.tableHeaderCell}>Delivery</th>
                        <th style={styles.tableHeaderCell}>Campus Coordinator</th>
                        <th style={{...styles.tableHeaderCell, textAlign: 'right'}}>Allocation to Subject Coordination Team</th>
                        <th style={{...styles.tableHeaderCell, textAlign: 'right'}}>Allocation</th>
                    </tr>
                </thead>
                <tbody>
                    {allocations.map((row) => {
                        const isEditing = editingId === row.id;
                        const lecturerAllocation = Math.max(0, row.baseAllocation - row.allocationToSubjectCoordinationTeam);

                        return (
                            <tr key={row.id} style={styles.tableRow}>
                                <td style={{...styles.tableCell, textAlign: 'center'}}>
                                    {isEditing ? (
                                        <div style={{display: 'flex', justifyContent: 'center', gap: '1rem'}}>
                                            <button style={styles.iconButton} onClick={handleSave} title="Save"><SaveIcon /></button>
                                            <button style={styles.iconButton} onClick={handleCancel} title="Cancel"><CancelIcon /></button>
                                        </div>
                                    ) : (
                                        <button style={styles.iconButton} onClick={() => handleEdit(row)} title="Edit"><EditIcon /></button>
                                    )}
                                </td>
                                <td style={styles.tableCell}>{row.delivery}</td>
                                <td style={styles.tableCell}>{row.campusCoordinator}</td>
                                <td style={{...styles.tableCell, textAlign: 'right'}}>
                                    {isEditing ? (
                                        <div>
                                            <input 
                                                type="number"
                                                value={editValue}
                                                onChange={handleInputChange}
                                                style={error ? {...styles.input, ...styles.inputError} : styles.input}
                                                min="0"
                                                max={row.baseAllocation}
                                                step="0.1"
                                            />
                                            {error && <small style={styles.errorMessage}>{error}</small>}
                                        </div>
                                    ) : (
                                        `${row.allocationToSubjectCoordinationTeam.toFixed(1)}%`
                                    )}
                                </td>
                                <td style={{...styles.tableCell, textAlign: 'right', fontWeight: '500'}}>
                                    {lecturerAllocation.toFixed(1)}%
                                </td>
                            </tr>
                        );
                    })}
                </tbody>
            </table>

            {/* This table is for the summary rows to ensure perfect alignment */}
            <table style={{...styles.table, marginTop: '1rem'}}>
                 <tbody>
                    <tr style={styles.summaryRow}>
                        <td style={styles.summaryCell}>Increase of base allocation</td>
                        <td style={{...styles.summaryCell, textAlign: 'right'}}>{calculatedData.increaseOfBaseAllocation.toFixed(1)}%</td>
                    </tr>
                    <tr style={{...styles.summaryRow, borderBottom: 'none'}}>
                        <td style={styles.summaryCell}>Allocation to Subject Coordinator: {subjectCoordinatorName}</td>
                        <td style={{...styles.summaryCell, textAlign: 'right'}}>{calculatedData.subjectCoordinatorAllocation.toFixed(2)}%</td>
                    </tr>
                </tbody>
            </table>

            <div style={styles.tabFooter}>
                <button style={styles.saveButton}>Save</button>
            </div>
        </div>
    );
}

